package com.xiaozai.photoscreen;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.graphics.*;import android.view.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.*;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;import fi.iki.elonen.NanoHTTPD;
public class MainActivity extends Activity{
 LinearLayout root,side,body;ImageView hero;List<File> pics=new ArrayList<>();int page=0,pos=0,delay=5;boolean en=false,playing=true,shuffle=false;Handler h=new Handler();PhotoServer server;
 String[] zh={"首页","图片管理","手机上传","播放设置","系统设置","关于"},us={"Home","Gallery","Phone Upload","Slideshow","System","About"};
 File dir(){File f=new File(getFilesDir(),"photos");f.mkdirs();return f;}String s(String a,String b){return en?b:a;}int dp(int x){return (int)(x*getResources().getDisplayMetrics().density+.5f);}
 TextView txt(String x,int z,int c,boolean bold){TextView t=new TextView(this);t.setText(x);t.setTextSize(z);t.setTextColor(c);if(bold)t.setTypeface(null,1);return t;}
 android.graphics.drawable.GradientDrawable shape(int c,int stroke){android.graphics.drawable.GradientDrawable d=new android.graphics.drawable.GradientDrawable();d.setColor(c);d.setCornerRadius(dp(12));if(stroke!=0)d.setStroke(dp(2),stroke);return d;}
 public void onCreate(Bundle b){super.onCreate(b);getWindow().addFlags(128);getWindow().getDecorView().setSystemUiVisibility(5894|1024|512);en=getPreferences(0).getBoolean("en",false);delay=getPreferences(0).getInt("delay",5);load();layout();server();h.post(tick);}
 Runnable tick=new Runnable(){public void run(){if(page==0&&playing&&!pics.isEmpty()){pos=shuffle?new Random().nextInt(pics.size()):(pos+1)%pics.size();render();}h.postDelayed(this,delay*1000L);}};
 void load(){pics.clear();File[] a=dir().listFiles();if(a!=null)for(File f:a)if(f.getName().matches("(?i).+\\.(jpg|jpeg|png|webp|gif|bmp)"))pics.add(f);Collections.sort(pics,(a1,b)->Long.compare(a1.lastModified(),b.lastModified()));if(pos>=pics.size())pos=0;}
 void layout(){root=new LinearLayout(this);root.setPadding(dp(14),dp(12),dp(14),dp(10));root.setBackgroundColor(0xff081326);setContentView(root);side=new LinearLayout(this);side.setOrientation(1);root.addView(side,new LinearLayout.LayoutParams(dp(155),-1));body=new LinearLayout(this);body.setOrientation(1);root.addView(body,new LinearLayout.LayoutParams(0,-1,1));render();}
 TextView btn(String x,Runnable r){TextView t=txt(x,15,-1,true);t.setGravity(17);t.setFocusable(true);t.setFocusableInTouchMode(true);t.setPadding(dp(8),dp(12),dp(8),dp(12));t.setBackground(shape(0xff193b61,0xff356c9e));t.setOnFocusChangeListener((v,has)->{v.animate().scaleX(has?1.045f:1f).scaleY(has?1.045f:1f).translationZ(has?dp(5):0).setDuration(160).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();});t.setOnClickListener(v->{v.animate().scaleX(0.97f).scaleY(0.97f).setDuration(65).withEndAction(()->v.animate().scaleX(v.hasFocus()?1.045f:1f).scaleY(v.hasFocus()?1.045f:1f).setDuration(110).start()).start();r.run();});return t;}
 void render(){side.removeAllViews();body.removeAllViews();TextView logo=txt("小李视觉",25,-1,true);logo.setGravity(17);side.addView(logo,new LinearLayout.LayoutParams(-1,dp(72)));for(int i=0;i<6;i++){final int n=i;TextView b=btn((en?us[i]:zh[i]),()->{page=n;render();});b.setBackground(shape(page==i?0xff15538d:0xff14243b,page==i?0xff53b5ff:0));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,dp(48));p.setMargins(dp(5),dp(5),dp(5),dp(5));side.addView(b,p);}TextView head=txt((en?us[page]:zh[page])+"                         Wi-Fi  ·  "+new java.text.SimpleDateFormat("HH:mm  yyyy/MM/dd",Locale.getDefault()).format(new Date()),17,-1,true);body.addView(head,new LinearLayout.LayoutParams(-1,dp(45)));if(page==0)home();if(page==1)gallery();if(page==2)upload();if(page==3)settings();if(page==4)system();if(page==5)body.addView(txt("小李视觉 V2.0\nAndroid TV 图片管理与展示",20,-1,true));body.setAlpha(0f);body.setTranslationY(dp(9));body.animate().alpha(1f).translationY(0f).setDuration(230).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();}
 Bitmap bitmap(File f,int size){try{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(f.getPath(),o);int n=1;while(o.outWidth/n>size*2||o.outHeight/n>size*2)n*=2;o.inJustDecodeBounds=false;o.inSampleSize=n;return BitmapFactory.decodeFile(f.getPath(),o);}catch(Exception e){return null;}}
 void home(){if(pics.isEmpty()){TextView empty=txt("还没有图片\n从手机上传、U盘或电视本地导入图片",24,-1,true);empty.setGravity(17);body.addView(empty,new LinearLayout.LayoutParams(-1,0,1));body.addView(btn("添加图片",()->pick()));}else{hero=new ImageView(this);hero.setScaleType(ImageView.ScaleType.FIT_CENTER);hero.setBackgroundColor(0xff101d30);body.addView(hero,new LinearLayout.LayoutParams(-1,0,1));hero.setAlpha(0f);hero.setImageBitmap(bitmap(pics.get(pos),1000));hero.animate().alpha(1f).setDuration(300).setInterpolator(new android.view.animation.DecelerateInterpolator()).start();LinearLayout strip=new LinearLayout(this);body.addView(strip,new LinearLayout.LayoutParams(-1,dp(76)));for(int i=0;i<Math.min(10,pics.size());i++){final int n=i;ImageView im=new ImageView(this);im.setImageBitmap(bitmap(pics.get(i),90));im.setScaleType(ImageView.ScaleType.CENTER_CROP);strip.addView(im,new LinearLayout.LayoutParams(dp(90),dp(65)));im.setOnClickListener(v->{pos=n;render();});}}LinearLayout cards=new LinearLayout(this);body.addView(cards,new LinearLayout.LayoutParams(-1,dp(55)));String[] a={"图片管理","手机上传","播放设置","存储管理","关于我们"};int[] d={1,2,3,4,5};for(int i=0;i<a.length;i++){final int n=d[i];TextView b=btn(a[i],()->{page=n;render();});cards.addView(b,new LinearLayout.LayoutParams(0,-1,1));}body.addView(txt("图片数量："+pics.size()+"     "+(playing?"正在播放":"已暂停")+"     "+(pics.isEmpty()?"0/0":(pos+1)+"/"+pics.size()),13,0xffa9bfdc,false));}
 void gallery(){body.addView(txt("图库共 "+pics.size()+" 张图片（选择图片进行操作）",16,-1,true));ScrollView sc=new ScrollView(this);body.addView(sc,new LinearLayout.LayoutParams(-1,0,1));GridLayout g=new GridLayout(this);g.setColumnCount(4);sc.addView(g);for(int i=0;i<pics.size();i++){final int n=i;LinearLayout cell=new LinearLayout(this);cell.setOrientation(1);ImageView im=new ImageView(this);im.setImageBitmap(bitmap(pics.get(i),140));im.setScaleType(ImageView.ScaleType.CENTER_CROP);cell.addView(im,new LinearLayout.LayoutParams(dp(140),dp(90)));cell.addView(txt(pics.get(i).getName(),10,-1,false));cell.setFocusable(true);cell.setOnFocusChangeListener((v,has)->v.animate().scaleX(has?1.035f:1f).scaleY(has?1.035f:1f).setDuration(150).start());cell.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(pics.get(n).getName()).setItems(new String[]{"播放","删除"},(x,w)->{if(w==0){pos=n;page=0;render();}else new AlertDialog.Builder(this).setMessage("只删除图库副本，不影响原文件。").setNegativeButton("取消",null).setPositiveButton("删除",(q,z)->{pics.get(n).delete();load();render();}).show();}).show());g.addView(cell);}}
 void pick(){Intent i=new Intent("android.intent.action.OPEN_DOCUMENT");i.addCategory("android.intent.category.OPENABLE");i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);startActivityForResult(i,5);}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==5&&c==-1&&d!=null)new Thread(()->{try{if(d.getClipData()!=null)for(int i=0;i<d.getClipData().getItemCount();i++)copy(d.getClipData().getItemAt(i).getUri());else if(d.getData()!=null)copy(d.getData());}catch(Exception e){}runOnUiThread(()->{load();page=0;render();});}).start();}
 void copy(android.net.Uri u)throws Exception{String name="image_"+System.currentTimeMillis()+".jpg";try(InputStream in=getContentResolver().openInputStream(u);OutputStream o=new FileOutputStream(new File(dir(),name))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)o.write(b,0,n);}}
 String ip(){try{for(Enumeration<NetworkInterface> e=NetworkInterface.getNetworkInterfaces();e.hasMoreElements();)for(Enumeration<InetAddress>a=e.nextElement().getInetAddresses();a.hasMoreElements();){InetAddress x=a.nextElement();if(x instanceof Inet4Address&&!x.isLoopbackAddress())return x.getHostAddress();}}catch(Exception e){}return "127.0.0.1";}
 void upload(){body.addView(txt("手机与电视连接同一 Wi-Fi，扫描二维码上传图片",17,-1,false));try{String u="http://"+ip()+":8765/";BitMatrix m=new MultiFormatWriter().encode(u,BarcodeFormat.QR_CODE,350,350);Bitmap b=Bitmap.createBitmap(350,350,Bitmap.Config.RGB_565);for(int x=0;x<350;x++)for(int y=0;y<350;y++)b.setPixel(x,y,m.get(x,y)?0xff000000:-1);ImageView q=new ImageView(this);q.setImageBitmap(b);body.addView(q,new LinearLayout.LayoutParams(dp(220),dp(220)));body.addView(txt(u,14,-1,false));}catch(Exception e){}body.addView(btn("重新生成二维码",()->render()));}
 void settings(){body.addView(txt("播放间隔",17,-1,true));for(int n:new int[]{3,5,10,15,30,60})body.addView(btn(n+" 秒"+(delay==n?" ✓":""),()->{delay=n;getPreferences(0).edit().putInt("delay",n).apply();render();}));body.addView(btn("播放 / 暂停",()->{playing=!playing;render();}));body.addView(btn("顺序 / 随机播放",()->{shuffle=!shuffle;render();}));body.addView(btn("上一张",()->{if(!pics.isEmpty()){pos=(pos+pics.size()-1)%pics.size();render();}}));body.addView(btn("下一张",()->{if(!pics.isEmpty()){pos=(pos+1)%pics.size();render();}}));}
 void system(){long z=0;for(File f:pics)z+=f.length();body.addView(txt("图片数量："+pics.size()+"\n图库占用："+(z/1048576)+" MB\n剩余空间："+(dir().getFreeSpace()/1048576)+" MB",17,-1,false));body.addView(btn(en?"简体中文":"English",()->{en=!en;getPreferences(0).edit().putBoolean("en",en).apply();render();}));body.addView(btn("导入图片 / U盘",()->pick()));}
 void server(){try{if(server!=null)server.stop();server=new PhotoServer(8765,dir(),()->runOnUiThread(()->{load();if(page==0)render();}));server.start(NanoHTTPD.SOCKET_READ_TIMEOUT,false);}catch(Exception e){}}
 public boolean onKeyDown(int k,KeyEvent e){if(k==KeyEvent.KEYCODE_MENU){new AlertDialog.Builder(this).setItems(new String[]{"下一张","暂停 / 继续","图片管理"},(d,w)->{if(w==0&&!pics.isEmpty())pos=(pos+1)%pics.size();if(w==1)playing=!playing;if(w==2)page=1;render();}).show();return true;}return super.onKeyDown(k,e);}
 public void onBackPressed(){if(page!=0){page=0;render();}else super.onBackPressed();}protected void onDestroy(){h.removeCallbacks(tick);if(server!=null)server.stop();super.onDestroy();}
 static class PhotoServer extends NanoHTTPD{File dir;Runnable changed;PhotoServer(int p,File f,Runnable r)throws IOException{super(p);dir=f;changed=r;}public Response serve(IHTTPSession s){try{if(Method.GET.equals(s.getMethod()))return newFixedLengthResponse("<meta charset='utf-8'><meta name='viewport' content='width=device-width'><body style='background:#101827;color:white;font:18px Arial;padding:24px'><h2>小李视觉图片上传</h2><input id='f' type='file' accept='image/*' multiple><button onclick='go()'>开始上传</button><p id='m'>选择图片</p><script>async function go(){for(let x of f.files){let r=await fetch('/up?name='+encodeURIComponent(x.name),{method:'POST',body:x});if(!r.ok){m.innerText='上传失败';return}m.innerText='已上传 '+x.name}m.innerText='上传完成'}</script>");if(Method.POST.equals(s.getMethod())&&s.getUri().equals("/up")){Map<String,String> m=new HashMap<>();s.parseBody(m);String tmp=m.get("postData");if(tmp==null)return newFixedLengthResponse(Response.Status.BAD_REQUEST,"text/plain","empty");String n=s.getParms().get("name");if(n==null)n="photo.jpg";n=new File(n).getName().replaceAll("[^A-Za-z0-9._-]","_");if(!n.matches("(?i).+\\.(jpg|jpeg|png|webp|gif|bmp)$"))n+=".jpg";try(InputStream in=new FileInputStream(tmp);OutputStream o=new FileOutputStream(new File(dir,System.currentTimeMillis()+"_"+n))){byte[] b=new byte[8192];int x;while((x=in.read(b))>0)o.write(b,0,x);}changed.run();return newFixedLengthResponse("OK");}return newFixedLengthResponse(Response.Status.NOT_FOUND,"text/plain","404");}catch(Exception e){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain",e.toString());}}}
}